  for (const o of p.pipeline.top.slice(0, 5)) L.push(`  - ${sanitizarTexto(o.empresa)} (${sanitizarTexto(o.vendedor)}): ${brl(o.total)}, vence em ${o.diasParaVencer} dia(s), chance hist\xF3rica ${pct(o.taxaFaixaPct, 0)}.`);
  L.push("");
