function decodificarImagem(imagem, maximoBytes, nome) {
  const base64 = imagem.dataBase64.replace(/^data:[^,]+,/, "");
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(base64)) throw new Error(`A ${nome} n\xE3o \xE9 uma imagem v\xE1lida.`);
  const buffer = Buffer.from(base64, "base64");
  if (buffer.length > maximoBytes) throw new Error(`A ${nome} ficou grande demais (${(buffer.length / 1e6).toFixed(1)} MB; o m\xE1ximo \xE9 ${(maximoBytes / 1e6).toFixed(1)} MB).`);
  const confere = imagem.mimeType === "image/png" ? ehPng(buffer) : ehJpeg(buffer);
  if (!confere) throw new Error(`A ${nome} n\xE3o \xE9 um ${imagem.mimeType === "image/png" ? "PNG" : "JPG"} v\xE1lido.`);
  return { imageBuffer: buffer, mimeType: imagem.mimeType };
}
