  if (!db5) {
    respostaErro(res, 503, "O banco de dados est\xE1 indispon\xEDvel.");
    return;
  }
  const linhas = await db5.select().from(propostas).where(sql21`left(${propostas.observacoes}, ${PREFIXO_ESTUDIO.length}) = ${PREFIXO_ESTUDIO}`).orderBy(desc21(propostas.createdAt));
